// Count subarrays whose sum equals k using prefix sums + a hashmap.
int subarraySum(vector<int>& nums, int k) {
    unordered_map<long long,int> seen{{0, 1}};   // empty prefix
    long long prefix = 0; int count = 0;
    for (int x : nums) {
        prefix += x;
        if (seen.count(prefix - k)) count += seen[prefix - k];
        seen[prefix]++;
    }
    return count;
}
